# Utvidelse: mekanikk, opp til 10 spørsmål per vanskelighet per tema. Kjøres inne i lag_bank.py.
tema("kinematikk")
pf,ka,td="posisjon-fart-akselerasjon","konstant-akselerasjon","to-dimensjoner"
q(pf,L,30,"En løper bruker 80 s på 400 m. Hva er gjennomsnittsfarten?","5.0 m/s",["r|0.20 m/s","r|320 m/s","b|80 m/s"],"$v = s/t$.",400/80)
q(pf,L,30,"Hva er 72 km/h målt i m/s?","20 m/s",["r|259 m/s","r|2.0 m/s","b|72 m/s"],"Del på 3.6 for å gå fra km/h til m/s.",72/3.6)
q(pf,L,20,"Hva forteller arealet under en graf av fart mot tid?","Strekningen",["b|Akselerasjonen","b|Farten","b|Tiden"],"Fart ganger tid er strekning.")
q(pf,L,30,"En syklist kjører 3.0 km mot øst og så 3.0 km tilbake til start. Hva er forflytningen?","0 km",["b|6.0 km","b|3.0 km","b|1.5 km"],"Forflytning er avstanden fra start til slutt, med retning.",0)
q(ka,L,30,"En bil har farten 5.0 m/s og akselererer med 3.0 m/s² i 2.0 s. Hva er farten etterpå?","11 m/s",["r|6.0 m/s","r|16 m/s","b|8.0 m/s"],"$v = v_0 + at$.",5+3*2)
q(ka,L,40,"En kloss starter fra ro med akselerasjonen 4.0 m/s². Hvor langt kommer den på 3.0 s?","18 m",["r|36 m","r|6.0 m","b|12 m"],"$s = \\frac{1}{2}at^2$.",.5*4*9)
q(td,L,30,"To like baller slippes og kastes horisontalt samtidig fra samme høyde. Hvilken lander først uten luftmotstand?","De lander samtidig",["b|Den som slippes","b|Den som kastes","b|Det avhenger av massen"],"Bevegelsen loddrett er den samme for begge.")
q(ka,M,90,"En bil øker farten jevnt fra 12 m/s til 28 m/s på 4.0 s. Hvor langt kjører den?","80 m",["r|160 m","r|48 m","b|112 m"],"$s = \\frac{1}{2}(v_0 + v)t$.",.5*40*4)
q(ka,M,90,"En ball kastes rett opp med 15 m/s. Hvor høyt når den?","11 m",["r|23 m","r|1.5 m","b|15 m"],"$h = v_0^2/(2\\mathrm{g})$.",225/(2*g))
q(ka,M,90,"En ball kastes rett opp med 12 m/s. Hvor lang tid går før den er tilbake i utgangspunktet?","2.4 s",["r|1.2 s","r|4.9 s","b|12 s"],"$t = 2v_0/\\mathrm{g}$.",24/g)
q(pf,M,120,"En bil kjører 60 km med 60 km/h og deretter 60 km med 30 km/h. Hva er gjennomsnittsfarten?","40 km/h",["r|90 km/h","r|20 km/h","b|45 km/h"],"Total strekning 120 km delt på total tid 3.0 h.",120/3)
q(pf,M,90,"Posisjonen er $x = 3.0t^2$, med $x$ i meter og $t$ i sekunder. Hva er farten ved $t = 3.0$ s?","18 m/s",["r|9.0 m/s","r|54 m/s","b|27 m/s"],"$v = \\mathrm{d}x/\\mathrm{d}t = 6.0t$.",6*3)
q(td,M,60,"En ball har startfarten 25 m/s i 37° over horisontalen. Hva er den horisontale fartskomponenten?","20 m/s",["r|15 m/s","r|31 m/s","b|25 m/s"],"$v_x = v_0\\cos\\theta$.",25*cos(radians(37)))
q(td,M,40,"Hva gjelder farten i toppunktet i et skrått kast uten luftmotstand?","Den er bare horisontal",["b|Den er null","b|Den er bare loddrett","b|Den er lik startfarten"],"Den loddrette komponenten er null i toppunktet, mens den horisontale er uendret.")
q(ka,V,180,"En bilist kjører i 25 m/s og har reaksjonstid 1.0 s. Deretter bremser bilen med 5.0 m/s². Hvor lang er stopplengden?","88 m",["r|150 m","r|50 m","b|63 m"],"Reaksjon: 25 m. Bremsing: $v_0^2/(2a) = 62.5\\ \\mathrm{m}$.",25+625/10)
q(ka,V,240,"En stein faller fra ro og bruker det siste sekundet på de siste 25 m. Fra hvilken høyde falt den?","46 m",["r|31 m","r|91 m","b|25 m"],"Fart ved starten av siste sekund: $25 - \\mathrm{g}/2 = 20.1\\ \\mathrm{m/s}$. Legg ett sekund til falltiden.",.5*g*((25-g/2)/g+1)**2)
q(ka,V,240,"En ballong stiger med 5.0 m/s. En stein slippes fra den i 40 m høyde. Hvor lang tid tar steinen til bakken?","3.4 s",["r|2.4 s","r|6.8 s","b|2.9 s"],"Steinen starter med 5.0 m/s oppover: $-40 = 5.0t - \\frac{1}{2}\\mathrm{g}t^2$.",(5+sqrt(25+2*g*40))/g)
q(td,V,120,"En ball kastes med 15 m/s i 45° fra flatt underlag. Hva er kastlengden?","23 m",["r|11 m","r|16 m","b|15 m"],"$x = v_0^2\\sin(2\\theta)/\\mathrm{g}$.",225/g)
q(td,V,240,"En stein kastes horisontalt med 12 m/s fra et 10 m høyt stup. Hvor stor vinkel med horisontalen har farten når steinen treffer bakken?","49°",["r|41°","r|60°","b|0°"],"$v_y = \\sqrt{2\\mathrm{g}h}$ og $\\tan\\theta = v_y/v_x$.",degrees(atan(sqrt(2*g*10)/12)))
q(td,V,240,"En ball kastes med 15 m/s fra flatt underlag og skal lande 20 m unna. Hva er den laveste utgangsvinkelen som virker?","30°",["r|61°","r|15°","b|45°"],"$\\sin(2\\theta) = x\\mathrm{g}/v_0^2 = 0.872$.",degrees(__import__('math').asin(20*g/225))/2)
q(pf,V,150,"En gjenstand starter fra ro med akselerasjonen $a = 2.0t$, med $a$ i m/s² og $t$ i sekunder. Hva er farten ved $t = 3.0$ s?","9.0 m/s",["r|18 m/s","r|3.0 m/s","b|6.0 m/s"],"$v = \\int a\\ \\mathrm{d}t = t^2$.",9)

tema("sirkelbevegelse")
sp,sk="sentripetal","sirkel-krefter"
q(sp,L,20,"Hva er perioden i en sirkelbevegelse?","Tiden for én runde",["b|Antall runder per sekund","b|Banefarten","b|Radien"],"Frekvensen er antall runder per sekund, og perioden er tiden for én runde.")
q(sp,L,30,"En sirkelbevegelse har perioden 4.0 s. Hva er frekvensen?","0.25 Hz",["r|4.0 Hz","r|2.5 Hz","b|1.0 Hz"],"$f = 1/T$.",.25)
q(sp,L,20,"Hvilken retning har farten i en sirkelbevegelse?","Langs tangenten til banen",["b|Inn mot sentrum","b|Ut fra sentrum","b|Den har ingen bestemt retning"],"Farten står hele tiden vinkelrett på radien.")
q(sp,L,30,"Farten i en sirkelbane dobles, og radien er den samme. Hvor mange ganger større blir sentripetalakselerasjonen?","4 ganger",["r|8 ganger","b|2 ganger","b|Den er uendret"],"$a = v^2/r$.",4)
q(sk,L,30,"Et legeme på 2.0 kg har sentripetalakselerasjonen 3.0 m/s². Hvor stor er sentripetalkraften?","6.0 N",["r|1.5 N","r|0.67 N","b|5.0 N"],"$F = ma$.",6)
q(sk,L,20,"En stein svinges i en snor, og snora ryker. Hvor går steinen?","Rett fram langs tangenten",["b|Rett ut fra sentrum","b|Rett inn mot sentrum","b|Videre i sirkelen"],"Uten kraft mot sentrum fortsetter steinen i fartsretningen.")
q(sk,L,20,"En stein svinges i en horisontal sirkel i en snor på et friksjonsfritt bord. Hva gir sentripetalkraften?","Snordraget",["b|Farten","b|Normalkraften","b|En egen sentrifugalkraft"],"Snora er det eneste som drar inn mot sentrum.")
q(sp,M,90,"Et hjul med radius 0.30 m roterer med frekvensen 5.0 Hz. Hva er banefarten ytterst på hjulet?","9.4 m/s",["r|1.5 m/s","r|4.7 m/s","b|5.0 m/s"],"$v = 2\\pi r f$.",2*pi*.3*5)
q(sp,M,120,"Hva er banefarten til et punkt på ekvator på grunn av Jordas rotasjon? Bruk $R = 6.37\\cdot 10^6$ m og perioden 24 h.","0.46 km/s",["r|1.7 Mm/s","r|0.23 km/s","b|7.9 km/s"],"$v = 2\\pi R/T$ med $T$ i sekunder.",2*pi*RE/86400/1000)
q(sp,M,90,"En kule går i en sirkel med radius 0.50 m og perioden 1.0 s. Hva er sentripetalakselerasjonen?","20 m/s²",["r|3.1 m/s²","r|9.9 m/s²","b|0 m/s²"],"$a = 4\\pi^2 r/T^2$.",4*pi**2*.5)
q(sk,M,90,"En stein på 0.20 kg svinges i en horisontal sirkel med radius 0.80 m og farten 4.0 m/s. Hvor stor er sentripetalkraften?","4.0 N",["r|1.0 N","r|3.2 N","b|2.0 N"],"$F = mv^2/r$.",.2*16/.8)
q(sk,M,120,"En bil på 1000 kg kjører over en bakketopp med krumningsradius 50 m i 15 m/s. Hvor stor er normalkraften?","5.3 kN",["r|14 kN","r|4.5 kN","b|9.8 kN"],"$N = m(\\mathrm{g} - v^2/r)$.",1000*(g-225/50)/1000)
q(sk,M,120,"En bil på 800 kg kjører gjennom bunnen av en dal med krumningsradius 40 m i 20 m/s. Hvor stor er normalkraften?","16 kN",["r|0.15 kN","r|8.0 kN","b|7.8 kN"],"$N = m(\\mathrm{g} + v^2/r)$.",800*(g+10)/1000)
q(sk,M,60,"Radien i en flat sving firedobles, og friksjonstallet er det samme. Hvor mange ganger større blir høyeste fart?","2 ganger",["r|16 ganger","b|4 ganger","b|Den er uendret"],"$v_{\\text{maks}} = \\sqrt{\\mu_s\\mathrm{g}r}$.",2)
q(sk,V,180,"En kule på 0.50 kg svinges i en loddrett sirkel med radius 1.2 m. Farten i bunnen er 6.0 m/s. Hva er snordraget der?","20 N",["r|10 N","b|15 N","b|4.9 N"],"$S = m(\\mathrm{g} + v^2/r)$.",.5*(g+30))
q(sk,V,240,"En kule i ei snor med lengde 1.0 m går i en horisontal sirkel, og snora danner 30° med loddlinjen. Hva er perioden?","1.9 s",["r|2.0 s","r|1.4 s","b|Avhenger av massen til kula"],"$T = 2\\pi\\sqrt{l\\cos\\theta/\\mathrm{g}}$.",2*pi*sqrt(cos(radians(30))/g))
q(sk,V,240,"En vogn ruller friksjonsfritt inn i en loddrett sløyfe med radius 4.0 m. Fra hvilken høyde over bunnen må den minst starte for å holde kontakten på toppen?","10 m",["r|12 m","r|4.0 m","b|8.0 m"],"På toppen er $v^2 = \\mathrm{g}r$. Energibevaring gir $h = 2.5r$.",2.5*4)
q(sk,V,150,"En bil kjører over en bakketopp med krumningsradius 40 m. Ved hvilken fart mister den kontakten med veien?","20 m/s",["r|28 m/s","r|6.3 m/s","b|Avhenger av massen til bilen"],"$N = 0$ gir $v = \\sqrt{\\mathrm{g}r}$.",sqrt(g*40))
q(sk,V,240,"En person sitter 3.0 m fra aksen på en karusell, og $\\mu_s = 0.40$. Hva er korteste periode uten at personen glir?","5.5 s",["r|0.87 s","r|11 s","b|Avhenger av massen til personen"],"$\\mu_s\\mathrm{g} = 4\\pi^2 r/T^2$.",2*pi*sqrt(3/(.4*g)))
q(sp,V,120,"Minuttviseren på en klokke er 12 cm lang. Hva er farten til spissen?","0.21 mm/s",["r|13 mm/s","r|0.10 mm/s","b|0 mm/s"],"$v = 2\\pi r/T$ med $T = 3600\\ \\mathrm{s}$.",2*pi*.12/3600*1000)
q(sk,V,180,"En pilot på 80 kg flyr i 100 m/s gjennom bunnen av en loddrett sirkel med radius 250 m. Hvor stor kraft får piloten fra setet?","4.0 kN",["r|3.2 kN","r|2.4 kN","b|0.78 kN"],"$N = m(\\mathrm{g} + v^2/r)$.",80*(g+40)/1000)

tema("newtons-lover")
nl,kp,ff,lm="newtons-lover","krefter-i-planet","friksjon-fjaer-snorer","luftmotstand"
q(nl,L,30,"Hva er tyngden til en person på 70 kg?","0.69 kN",["r|7.1 N","r|6.9 kN","b|70 N"],"$G = m\\mathrm{g}$.",70*g/1000)
q(nl,L,30,"Et legeme på 4.0 kg har akselerasjonen 3.0 m/s². Hva er kraftsummen?","12 N",["r|1.3 N","r|0.75 N","b|7.0 N"],"$F = ma$.",12)
q(nl,L,20,"En bok ligger i ro på et bord. Hvor stor er normalkraften?","Lik tyngden til boka",["b|Null","b|Større enn tyngden","b|Mindre enn tyngden"],"Boka akselererer ikke, så kreftene oppveier hverandre.")
q(nl,L,30,"En kraft på 3.0 N virker mot høyre og en på 5.0 N mot venstre. Hva er kraftsummen?","2.0 N mot venstre",["r|8.0 N mot venstre","b|2.0 N mot høyre","b|Null"],"Krefter i motsatt retning trekkes fra hverandre.",2)
q(kp,L,30,"To krefter på 3.0 N og 4.0 N står vinkelrett på hverandre. Hvor stor er kraftsummen?","5.0 N",["r|1.0 N","r|12 N","b|7.0 N"],"$F = \\sqrt{3.0^2 + 4.0^2}\\ \\mathrm{N}$.",5)
q(ff,L,20,"Hvilken retning har friksjonskraften på en kloss som glir?","Mot bevegelsen",["b|Med bevegelsen","b|Vinkelrett opp fra underlaget","b|Rett ned"],"Friksjonen motvirker at flatene glir mot hverandre.")
q(lm,L,30,"Luftmotstanden er $L = kv^2$. Farten dobles. Hvor mange ganger større blir luftmotstanden?","4 ganger",["r|8 ganger","b|2 ganger","b|Den er uendret"],"Luftmotstanden går som farten i andre.",4)
q(nl,M,90,"En person på 60 kg står i en heis som akselererer oppover med 2.0 m/s². Hvor stor er normalkraften?","0.71 kN",["r|0.47 kN","r|0.12 kN","b|0.59 kN"],"$N = m(\\mathrm{g} + a)$.",60*(g+2)/1000)
q(nl,M,120,"Klosser på 2.0 kg og 3.0 kg står inntil hverandre på et friksjonsfritt golv. En kraft på 10 N skyver på den minste. Hvor stor kraft virker mellom klossene?","6.0 N",["r|4.0 N","r|2.0 N","b|10 N"],"$a = 2.0\\ \\mathrm{m/s^2}$, og den største klossen må ha $F = 3.0\\cdot 2.0\\ \\mathrm{N}$.",3*2)
q(kp,M,60,"En kraft på 40 N virker 30° over horisontalen. Hvor stor er den horisontale komponenten?","35 N",["r|20 N","r|46 N","b|40 N"],"$F_x = F\\cos\\theta$.",40*cos(radians(30)))
q(kp,M,90,"En kloss på 5.0 kg ligger på et skråplan med vinkel 40°. Hvor stor er normalkraften?","38 N",["r|32 N","r|64 N","b|49 N"],"$N = m\\mathrm{g}\\cos\\theta$.",5*g*cos(radians(40)))
q(ff,M,90,"En kasse på 20 kg står på et horisontalt golv med $\\mu_s = 0.50$. Hvor stor horisontal kraft trengs for å få den i gang?","98 N",["r|9.8 N","r|40 N","b|0.20 kN"],"$F = \\mu_s m\\mathrm{g}$.",.5*20*g)
q(ff,M,120,"Et lodd på 2.0 kg henger i to like, parallelle fjærer med stivhet 100 N/m. Hvor mye strekkes de?","9.8 cm",["r|20 cm","r|4.9 cm","b|0 cm"],"Fjærene deler lasten: $x = m\\mathrm{g}/(2k)$.",2*g/200*100)
q(lm,M,30,"Hva er akselerasjonen til en fallskjermhopper som har nådd terminalfarten?","Null",["b|$\\mathrm{g}$ nedover","b|$\\mathrm{g}/2$ nedover","b|Den øker jevnt"],"Luftmotstanden er like stor som tyngden, så kraftsummen er null.")
q(kp,V,180,"En kasse på 10 kg skyves med konstant fart oppover et skråplan med vinkel 30°, og $\\mu_k = 0.25$. Kraften er parallell med planet. Hvor stor er den?","70 N",["r|28 N","b|49 N","b|98 N"],"$F = m\\mathrm{g}(\\sin\\theta + \\mu_k\\cos\\theta)$.",10*g*(.5+.25*cos(radians(30))))
q(ff,V,240,"En vogn på 4.0 kg står på et bord med $\\mu_k = 0.20$ og er koblet over en lett trinse til et lodd på 3.0 kg som henger fritt. Hva er akselerasjonen?","3.1 m/s²",["r|5.3 m/s²","r|7.4 m/s²","b|4.2 m/s²"],"$a = \\mathrm{g}(3.0 - 0.20\\cdot 4.0)/7.0$.",g*(3-.8)/7)
q(nl,V,180,"En heis på 1200 kg er på vei ned i 4.0 m/s og bremser jevnt til stopp på 8.0 m. Hva er draget i kabelen?","13 kN",["r|11 kN","r|1.2 kN","b|12 kN"],"$a = v^2/(2s) = 1.0\\ \\mathrm{m/s^2}$ oppover, så $S = m(\\mathrm{g} + a)$.",1200*(g+1)/1000)
q(kp,V,240,"En kasse på 10 kg dras langs et golv med en kraft på 50 N som virker 37° over horisontalen, og $\\mu_k = 0.30$. Hva er akselerasjonen?","2.0 m/s²",["r|4.0 m/s²","r|5.0 m/s²","b|1.1 m/s²"],"Normalkraften blir mindre: $N = m\\mathrm{g} - F\\sin\\theta$.",(50*cos(radians(37))-.3*(10*g-50*sin(radians(37))))/10)
q(ff,V,240,"En kloss på 2.0 kg ligger oppå en kloss på 5.0 kg på et friksjonsfritt golv, med $\\mu_s = 0.40$ mellom dem. Hva er største horisontale kraft på den nederste uten at den øverste glir?","27 N",["r|7.8 N","r|12 N","b|20 N"],"Største felles akselerasjon er $\\mu_s\\mathrm{g}$, og hele massen må ha den.",7*.4*g)
q(lm,V,120,"To kuler har samme konstant $k$ i $L = kv^2$, men den ene har fire ganger så stor masse. Hvor mange ganger større er terminalfarten dens?","2 ganger",["r|16 ganger","b|4 ganger","b|Den er uendret"],"$v = \\sqrt{m\\mathrm{g}/k}$.",2)
q(lm,V,150,"En ball på 0.50 kg er på vei rett opp i 20 m/s, med $L = kv^2$ og $k = 0.010$ kg/m. Hvor stor er akselerasjonen?","18 m/s²",["r|1.8 m/s²","r|8.0 m/s²","b|9.8 m/s²"],"Tyngde og luftmotstand virker begge nedover: $a = \\mathrm{g} + kv^2/m$.",g+.01*400/.5)

tema("bevegelsesmengde")
ks,ko="kraftstot","kollisjoner"
q(ks,L,20,"Hvilken enhet har bevegelsesmengde?","kg m/s",["b|kg m/s²","b|J","b|W"],"$p = mv$.")
q(ks,L,20,"Hva slags størrelse er bevegelsesmengde?","En vektor i samme retning som farten",["b|En skalar","b|En vektor mot farten","b|En vektor inn mot sentrum"],"Massen er positiv, så $\\vec p = m\\vec v$ peker samme vei som farten.")
q(ks,L,30,"Et legeme på 3.0 kg har bevegelsesmengden 12 kg m/s. Hva er farten?","4.0 m/s",["r|36 m/s","r|0.25 m/s","b|9.0 m/s"],"$v = p/m$.",4)
q(ks,L,20,"Hva er kraftstøtet på et legeme lik?","Endringen i bevegelsesmengden",["b|Endringen i energien","b|Massen til legemet","b|Arbeidet på legemet"],"$F\\Delta t = \\Delta p$.")
q(ko,L,40,"En vogn på 1.0 kg med farten 6.0 m/s treffer en vogn på 2.0 kg i ro, og de henger sammen. Hva er farten etterpå?","2.0 m/s",["r|3.0 m/s","r|6.0 m/s","b|0 m/s"],"$V = 6.0/3.0\\ \\mathrm{m/s}$.",2)
q(ko,L,20,"Hva kjennetegner et fullstendig uelastisk støt?","Legemene henger sammen, og kinetisk energi går tapt",["b|Bevegelsesmengden går tapt","b|Massen endres","b|Det virker ingen krefter"],"Bevegelsesmengden er bevart, men ikke den kinetiske energien.")
q(ko,L,20,"En gjenstand i ro sprenges i biter. Hva er den samlede bevegelsesmengden etterpå?","Null",["b|Større enn null","b|Lik den samlede kinetiske energien","b|Den avhenger av antall biter"],"Bevegelsesmengden var null før, og indre krefter endrer den ikke.")
q(ks,M,90,"En bil på 1500 kg øker farten fra 0 til 20 m/s på 10 s. Hvor stor er middelkraften?","3.0 kN",["r|30 kN","r|0.30 kN","b|15 kN"],"$F = \\Delta p/\\Delta t$.",1500*20/10/1000)
q(ks,M,90,"En ball på 0.50 kg treffer en vegg med 10 m/s og spretter rett tilbake med 8.0 m/s. Hvor stor er endringen i bevegelsesmengde?","9.0 kg m/s",["r|18 kg m/s","r|4.5 kg m/s","b|1.0 kg m/s"],"Retningen snus, så fartene legges sammen.",.5*18)
q(ks,M,90,"Kraften i et støt øker jevnt til 100 N og avtar jevnt til null, alt på 0.020 s. Hvor stort er kraftstøtet?","1.0 N s",["r|2.0 N s","r|0.50 N s","b|100 N s"],"Arealet under grafen er en trekant.",.5*100*.02)
q(ko,M,90,"En vogn på 5.0 kg med 2.0 m/s og en på 3.0 kg med 2.0 m/s kolliderer rett mot hverandre og henger sammen. Hva er farten etterpå?","0.50 m/s",["r|2.0 m/s","r|1.0 m/s","b|0 m/s"],"$V = (10 - 6.0)/8.0\\ \\mathrm{m/s}$.",.5)
q(ko,M,60,"To skøyteløpere på 60 kg og 40 kg står i ro og dytter hverandre. Den tyngste får farten 2.0 m/s. Hvilken fart får den letteste?","3.0 m/s",["r|1.3 m/s","r|5.0 m/s","b|2.0 m/s"],"Samlet bevegelsesmengde er null.",60*2/40)
q(ko,M,30,"Hva er bevart i et elastisk støt?","Bevegelsesmengde og kinetisk energi",["b|Bare bevegelsesmengde","b|Bare kinetisk energi","b|Ingen av dem"],"Det er nettopp bevaringen av kinetisk energi som gjør støtet elastisk.")
q(ks,M,40,"Hvorfor reduserer en kollisjonspute kraften på føreren?","Støttiden blir lengre",["b|Kraftstøtet blir mindre av seg selv","b|Bevegelsesmengden før støtet blir mindre","b|Massen til føreren øker"],"Samme endring i bevegelsesmengde over lengre tid gir mindre kraft.")
q(ko,V,180,"En kule på 2.0 kg med 3.0 m/s støter elastisk og sentralt mot en kule på 1.0 kg i ro. Hva er farten til den letteste etterpå?","4.0 m/s",["r|1.0 m/s","r|6.0 m/s","b|2.0 m/s"],"$v_2 = 2m_1 v/(m_1 + m_2)$.",2*2*3/3)
q(ko,V,240,"En kule på 10 g med 300 m/s skytes inn i en trekloss på 2.0 kg som henger i snorer. Hvor høyt svinger klossen?","11 cm",["r|7.6 cm","r|23 cm","b|4.6 km"],"Først bevegelsesmengde: $V = mv/(m+M)$. Så energi: $h = V^2/(2\\mathrm{g})$.",((.01*300/2.01)**2/(2*g))*100)
q(ko,V,240,"En gjenstand på 3.0 kg i ro sprenges i biter på 1.0 kg og 2.0 kg. Samlet kinetisk energi blir 12 J. Hvilken fart får den minste?","4.0 m/s",["r|2.0 m/s","r|4.9 m/s","b|3.5 m/s"],"Bitene får samme $p$, og $p^2/2\\cdot(1/1.0 + 1/2.0) = 12$.",4)
q(ks,V,150,"En vannstråle med 2.0 kg/s treffer en vegg i 10 m/s og stopper. Hvor stor kraft virker på veggen?","20 N",["r|5.0 N","r|40 N","b|2.0 N"],"$F = (\\Delta m/\\Delta t)v$.",20)
q(ko,V,120,"To like kuler støter elastisk, men ikke sentralt, og den ene lå i ro. Hvilken vinkel er det mellom fartene etterpå?","90°",["b|0°","b|45°","b|180°"],"Bevaring av bevegelsesmengde og energi gir Pythagoras for fartene.",90)
q(ko,V,180,"En person på 70 kg løper i 4.0 m/s og hopper på en vogn på 50 kg som ruller i 2.0 m/s samme vei. Hva er farten etterpå?","3.2 m/s",["r|1.5 m/s","r|6.0 m/s","b|3.0 m/s"],"$V = (70\\cdot 4.0 + 50\\cdot 2.0)/120$.",380/120)
q(ks,V,150,"En rakett slipper ut 5.0 kg gass per sekund med 2.0 km/s i forhold til raketten. Hvor stor er skyvekraften?","10 kN",["r|2.5 kN","r|10 N","b|49 N"],"$F = (\\Delta m/\\Delta t)v$.",5*2000/1000)

