q(eb,M,90,"En pendelkule slippes fra 0.20 m over det laveste punktet. Hva er farten i bunnen?","2.0 m/s",["r|1.4 m/s","r|3.9 m/s","b|Kan ikke beregnes uten massen"],"$v = \\sqrt{2\\mathrm{g}h}$.",sqrt(2*g*.2))
q(eb,M,90,"En ball kastes rett opp med 8.0 m/s. Bruk energibevaring: Hvor høyt når den?","3.3 m",["r|6.5 m","r|0.82 m","b|8.0 m"],"$h = v^2/(2\\mathrm{g})$.",64/(2*g))
