q(eb,V,150,"En berg-og-dal-vogn starter fra ro 30 m over bakken. Hva er farten når den er 10 m over bakken, uten friksjon?","20 m/s",["r|14 m/s","r|17 m/s","b|24 m/s"],"Bare høydeforskjellen på 20 m teller.",sqrt(2*g*20))
