q(ep,V,240,"En bil på 1200 kg kjører i 25 m/s oppover en bakke med helning 5.0°. Samlet motstand er 400 N. Hvor stor effekt trengs?","36 kW",["r|0.29 MW","b|26 kW","b|10 kW"],"$P = v(m\\mathrm{g}\\sin\\theta + F_{\\text{motstand}})$.",25*(1200*g*sin(radians(5))+400)/1000)
q(ep,V,180,"Et kraftverk har fallhøyde 100 m, vannføring 20 m³/s og virkningsgrad 90 %. Hvor stor effekt gir det?","18 MW",["r|20 MW","r|16 MW","b|18 kW"],"$P = \\eta\\rho Q\\mathrm{g}h$.",.9*1000*20*g*100/1e6)
