q(sa,L,20,"Hva er perioden til en geostasjonær satellitt?","24 h",["b|12 h","b|1 h","b|365 døgn"],"Den følger Jordas rotasjon.")
q(sa,L,20,"Hvorfor føler astronauter seg vektløse i bane rundt Jorda?","De er i fritt fall sammen med romskipet",["b|Det er ingen gravitasjon der","b|De er for langt unna Jorda","b|Det er ingen luft der"],"Gravitasjonen er nesten like stor som ved bakken, men ingenting holder dem oppe.")
q(sa,L,20,"Hva sier Keplers 1. lov om planetbanene?","De er ellipser med Sola i det ene brennpunktet",["b|De er sirkler med Sola i sentrum","b|Sola går i bane rundt planetene","b|De er rette linjer"],"Sirkelen er bare et spesialtilfelle av ellipsen.")
q(gl,M,120,"Hva er gravitasjonskraften mellom Jorda ($5.97\\cdot 10^{24}$ kg) og Månen ($7.35\\cdot 10^{22}$ kg) med avstanden $3.84\\cdot 10^8$ m?","1.98·10²⁰ N",["r|7.6·10²⁸ N","r|9.9·10¹⁹ N","b|7.2·10²³ N"],"$F = \\mathrm{G}Mm/r^2$.",G*ME*7.35e22/3.84e8**2/1e20)
q(gl,M,90,"Mars har massen $6.42\\cdot 10^{23}$ kg og radien $3.39\\cdot 10^6$ m. Hva er tyngdeakselerasjonen ved overflaten?","3.73 m/s²",["r|7.45 m/s²","r|1.86 m/s²","b|9.81 m/s²"],"$\\mathrm{g} = \\mathrm{G}M/R^2$.",G*6.42e23/3.39e6**2)
q(gl,M,60,"En planet har dobbelt så stor masse og dobbelt så stor radius som Jorda. Hvordan er tyngdeakselerasjonen der sammenliknet med på Jorda?","Halvparten så stor",["r|En firedel så stor","r|Dobbelt så stor","b|Like stor"],"$\\mathrm{g} = \\mathrm{G}M/R^2$ gir faktoren $2/4$.")
q(gl,M,120,"I hvilken høyde over bakken er tyngdeakselerasjonen halvparten av verdien ved overflaten? Bruk $R = 6.37$ Mm.","2.64 Mm",["r|6.37 Mm","r|3.19 Mm","b|1.3 Mm"],"$(R+h)^2 = 2R^2$ gir $h = (\\sqrt{2}-1)R$.",(sqrt(2)-1)*6.37)
q(sa,M,30,"Hvordan er banefarten til en satellitt i lav bane sammenliknet med en i høy bane?","Større",["b|Mindre","b|Like stor","b|Den er null i begge"],"$v = \\sqrt{\\mathrm{G}M/r}$ øker når $r$ minker.")
q(sa,M,120,"En satellitt går i sirkelbane med radius $7.0\\cdot 10^6$ m rundt Jorda ($M = 5.97\\cdot 10^{24}$ kg). Hva er perioden?","97 min",["r|16 min","r|1.6 min","b|24 h"],"$T = 2\\pi r/v$ med $v = \\sqrt{\\mathrm{G}M/r}$.",2*pi*7e6/sqrt(G*ME/7e6)/60)
q(sa,M,90,"Mars har banehalvakse 1.52 ganger Jordas. Hva er perioden til Mars, målt i år?","1.87 år",["r|1.52 år","r|2.31 år","b|1.00 år"],"Keplers 3. lov: $T = a^{3/2}$ med $a$ målt i Jordas baneradius.",1.52**1.5)
q(sa,V,180,"Hva er den samlede mekaniske energien til en satellitt på 1000 kg i sirkelbane med radius $7.0\\cdot 10^6$ m rundt Jorda ($M = 5.97\\cdot 10^{24}$ kg)?","−28 GJ",["r|−57 GJ","r|−14 GJ","b|+28 GJ"],"$E = -\\mathrm{G}Mm/(2r)$.",-G*ME*1000/(2*7e6)/1e9)
q(sa,V,240,"Hvor mye energi må tilføres en satellitt på 1000 kg for å flytte den fra sirkelbane med radius 7.0 Mm til 14 Mm? Bruk $M = 5.97\\cdot 10^{24}$ kg.","14 GJ",["r|28 GJ","r|7.1 GJ","b|0 J"],"$\\Delta E = \\frac{\\mathrm{G}Mm}{2}(1/r_1 - 1/r_2)$.",G*ME*1000/2*(1/7e6-1/14e6)/1e9)
q(gl,V,240,"Månens masse er $7.35\\cdot 10^{22}$ kg, Jordas er $5.97\\cdot 10^{24}$ kg, og avstanden er 384 Mm. Hvor langt fra Jorda er gravitasjonskreftene fra de to like store?","346 Mm",["r|300 Mm","r|42 Mm","b|192 Mm"],"$x/(d-x) = \\sqrt{M/m}$.",384/(1+sqrt(7.35e22/ME)))
q(gl,V,120,"Tenk deg en sjakt til halve Jordas radius, og at Jorda har jevn tetthet. Hva er tyngdeakselerasjonen der?","4.91 m/s²",["r|2.45 m/s²","b|19.6 m/s²","b|0 m/s²"],"Inne i en jevn kule er tyngdeakselerasjonen proporsjonal med avstanden fra sentrum.",g/2)
q(sa,V,240,"Månen går rundt Jorda med radius $3.84\\cdot 10^8$ m og perioden 27.3 døgn. Hva gir dette for massen til Jorda?","6.0·10²⁴ kg",["r|9.6·10²³ kg","r|2.4·10²⁵ kg","b|7.4·10²² kg"],"$M = 4\\pi^2 r^3/(\\mathrm{G}T^2)$.",4*pi**2*3.84e8**3/(G*(27.3*86400)**2)/1e24)
q(sa,V,120,"Hvor mange ganger større er unnslipningsfarten enn sirkelbanefarten i samme avstand fra en planet?","√2 ganger",["r|2 ganger","r|4 ganger","b|1 gang"],"$v_u = \\sqrt{2\\mathrm{G}M/r}$ og $v = \\sqrt{\\mathrm{G}M/r}$.")
q(gl,V,240,"To stjerner, begge på $2.0\\cdot 10^{30}$ kg, går i sirkel om det felles massesenteret med avstand $1.0\\cdot 10^{11}$ m mellom seg. Hva er banefarten til hver?","26 km/s",["r|37 km/s","r|52 km/s","b|Stjernene står stille"],"Baneradien er $d/2$: $\\mathrm{G}m^2/d^2 = mv^2/(d/2)$.",sqrt(G*2e30/(2*1e11))/1000)

tema("svingninger")
ha,pe="harmoniske","pendel"
q(ha,L,30,"En pendel gjør 10 svingninger på 5.0 s. Hva er perioden?","0.50 s",["r|2.0 s","r|50 s","b|5.0 s"],"$T = t/n$.",.5)
q(ha,L,30,"En svingning har frekvensen 50 Hz. Hva er perioden?","20 ms",["r|50 ms","r|2.0 ms","b|50 s"],"$T = 1/f$.",20)
q(ha,L,20,"Hva er amplituden i en svingning?","Største utslag fra likevektsstillingen",["b|Tiden for én svingning","b|Antall svingninger per sekund","b|Avstanden mellom de to ytterpunktene"],"Avstanden mellom ytterpunktene er to amplituder.")
q(ha,L,20,"Hvilken retning har akselerasjonen i en harmonisk svingning?","Mot likevektsstillingen",["b|Bort fra likevektsstillingen","b|Alltid samme vei som farten","b|Alltid rett ned"],"$a = -\\omega^2 x$.")
q(ha,L,30,"En svingning har frekvensen 2.0 Hz. Hva er vinkelfrekvensen?","13 rad/s",["r|6.3 rad/s","r|3.1 rad/s","b|2.0 rad/s"],"$\\omega = 2\\pi f$.",4*pi)
q(pe,L,30,"Lengden på en pendel firedobles. Hvor mange ganger lengre blir perioden?","2 ganger",["r|16 ganger","b|4 ganger","b|Den er uendret"],"$T$ er proporsjonal med $\\sqrt{l}$.",2)
q(pe,L,20,"En kloss svinger i en fjær. Fjæra byttes med en stivere. Hva skjer med perioden?","Den minker",["b|Den øker","b|Den er uendret","b|Den blir null"],"$T = 2\\pi\\sqrt{m/k}$.")
q(ha,M,60,"En fjær med stivhet 50 N/m svinger med amplitude 0.20 m. Hva er den samlede energien?","1.0 J",["r|2.0 J","r|5.0 J","b|10 J"],"$E = \\frac{1}{2}kA^2$.",.5*50*.04)
q(ha,M,60,"En svingning er gitt ved $x = 0.050\\cos(4.0t)$, i SI-enheter. Hva er perioden?","1.6 s",["r|0.64 s","r|4.0 s","b|0.050 s"],"$T = 2\\pi/\\omega$.",2*pi/4)
q(ha,M,30,"Hvor i en harmonisk svingning er akselerasjonen størst i tallverdi?","I ytterpunktene",["b|I likevektsstillingen","b|Den er lik overalt","b|Halvveis ut mot ytterpunktene"],"Akselerasjonen er proporsjonal med utslaget.")
q(ha,M,90,"En kloss i en fjær har utslaget $x = A/2$. Hvor stor del av energien er fjærenergi?","25 %",["r|75 %","r|50 %","b|100 %"],"Fjærenergien går som $x^2$.",25)
q(pe,M,90,"Hva er perioden til en pendel med lengde 1.0 m på Månen, der tyngdeakselerasjonen er 1.62 m/s²?","4.9 s",["r|0.79 s","r|3.9 s","b|2.0 s"],"$T = 2\\pi\\sqrt{l/\\mathrm{g}_\\text{Månen}}$.",2*pi*sqrt(1/1.62))
q(pe,M,90,"Hvor lang må en pendel være for å ha perioden 1.0 s?","0.25 m",["r|1.6 m","r|0.50 m","b|1.0 m"],"$l = \\mathrm{g}T^2/(4\\pi^2)$.",g/(4*pi**2))
q(pe,M,90,"Et lodd strekker en fjær 0.20 m når det henger i ro. Hva blir perioden hvis det settes i svingninger?","0.90 s",["r|0.14 s","r|0.45 s","b|Kan ikke beregnes uten massen"],"$k = m\\mathrm{g}/x$ gir $T = 2\\pi\\sqrt{x/\\mathrm{g}}$.",2*pi*sqrt(.2/g))
q(ha,V,150,"En svingning har største fart 0.60 m/s og amplitude 0.10 m. Hva er største akselerasjon?","3.6 m/s²",["r|0.60 m/s²","r|36 m/s²","b|9.8 m/s²"],"$\\omega = v_{\\text{maks}}/A$ og $a_{\\text{maks}} = A\\omega^2$.",.1*36)
q(ha,V,180,"En svingning med perioden 1.2 s starter i $x = A$. Hvor lang tid tar det før $x = A/2$ første gang?","0.20 s",["r|0.60 s","r|0.10 s","b|0.30 s"],"$\\cos(\\omega t) = 1/2$ gir $\\omega t = \\pi/3$, altså $t = T/6$.",.2)
q(ha,V,120,"En fjær med stivhet 200 N/m svinger med samlet energi 0.25 J. Hva er amplituden?","5.0 cm",["r|3.5 cm","r|13 cm","b|25 cm"],"$A = \\sqrt{2E/k}$.",sqrt(.5/200)*100)
q(ha,V,150,"Amplituden i en dempet svingning minker med 10 % per periode. Hvor mange prosent av startamplituden er igjen etter 5 perioder?","59 %",["r|41 %","r|90 %","b|50 %"],"$0.90^5 = 0.59$.",100*.9**5)
q(pe,V,180,"En pendel med lengde 0.50 m henger i en heis som akselererer oppover med 2.0 m/s². Hva er perioden?","1.3 s",["r|1.6 s","r|0.46 s","b|1.4 s"],"Effektiv tyngdeakselerasjon er $\\mathrm{g} + a$.",2*pi*sqrt(.5/(g+2)))
q(pe,V,180,"En kloss på 0.50 kg henger i to like fjærer med stivhet 100 N/m koblet etter hverandre. Hva er perioden?","0.63 s",["r|0.44 s","r|0.10 s","b|0.31 s"],"Serie gir $k = 50\\ \\mathrm{N/m}$.",2*pi*sqrt(.5/50))
q(pe,V,240,"En jevn stav med lengde 1.0 m svinger om den ene enden ($I = ML^2/3$). Hva er perioden ved små utslag?","1.6 s",["r|1.2 s","r|2.9 s","b|2.0 s"],"$T = 2\\pi\\sqrt{2L/(3\\mathrm{g})}$.",2*pi*sqrt(2/(3*g)))
